/*
 * write-tracking-token.mjs — writes the Mixpanel project token for add-on usage tracking
 * (src/app/services/usage-tracking.ts) into a gitignored generated file.
 *
 * Read from the environment, never from a tracked file: set TAU_MIXPANEL_TOKEN in your shell's
 * credentials file. Never print the value — only whether it is set, and its length.
 *
 * Deliberately a separate script rather than code in prebuild.js: prebuild.js is Ex Libris's
 * file, and keeping it byte-identical to upstream/main means it merges for free on every
 * upstream sync. This code lived there from #74 until it was moved here. See *Syncing with
 * upstream ExLibris repo* in CLAUDE.md.
 *
 * Run by `npm run generate`, after prebuild.js and before select-view.mjs.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const trackingOutPath = path.join(root, 'src/app/state/tracking.generated.ts');

const rawToken = (process.env.TAU_MIXPANEL_TOKEN || '').trim();
const token = /^[A-Za-z0-9]+$/.test(rawToken) ? rawToken : '';
if (rawToken && !token) {
  console.warn('⚠ TAU_MIXPANEL_TOKEN is set but not alphanumeric — ignored; usage tracking stays off.');
}
fs.writeFileSync(
  trackingOutPath,
  '// GENERATED by scripts/write-tracking-token.mjs from $TAU_MIXPANEL_TOKEN — gitignored; do not edit or commit.\n' +
  `export const mixpanelProjectToken = '${token}';\n`
);
console.log(`✔ Usage-tracking token: ${token ? `set (length ${token.length})` : 'NOT set — tracking off in this build'}`);
